# Penelusuran melebar: mencari lintasan terpendek
# dalam graf tanpa bobot
from collections import deque

graf = {
    "A": {"B", "C"}, "B": {"A", "C", "D"}, "C": {"A", "B", "D"},
    "D": {"B", "C", "E"}, "E": {"D"},
}

def lintasan(graf, awal, tujuan):
    antre = deque([[awal]])
    dikunjungi = {awal}
    while antre:
        jalur = antre.popleft()
        if jalur[-1] == tujuan:
            return jalur
        for tetangga in sorted(graf[jalur[-1]]):
            if tetangga not in dikunjungi:
                dikunjungi.add(tetangga)
                antre.append(jalur + [tetangga])
    return None

print(lintasan(graf, "A", "E"))

